INSERT INTO `products` VALUES (1,5,'Botox 100-unit Vial','PRD-00001',NULL,'vial',8000.00,15000.00,24.000,5.000,NULL,0,1,NULL,NULL,'active','2026-09-19 07:34:33.433','2026-09-20 10:41:37.087',NULL,NULL,NULL,NULL),(2,5,'Hyaluronic Acid Filler 1ml','PRD-00002',NULL,'unit',10000.00,18000.00,15.000,3.000,NULL,0,1,NULL,NULL,'active','2026-09-19 07:34:33.457','2026-09-19 07:34:33.457',NULL,NULL,NULL,NULL),(3,1,'Chemical Peel Solution','PRD-00003',NULL,'ml',500.00,0.00,500.000,100.000,NULL,0,1,NULL,NULL,'active','2026-09-19 07:34:33.484','2026-09-19 07:34:33.484',NULL,NULL,NULL,NULL),(4,3,'Facial Cleansing Gel','PRD-00004','A gel-based facial cleanser that lathers with water to wash away daily buildup from the skin.','bottle',350.00,850.00,46.000,10.000,NULL,1,1,NULL,NULL,'active','2026-09-19 07:34:33.506','2026-10-03 16:22:51.400',NULL,'Used morning and/or evening to cleanse the face by lifting away dirt, excess oil, makeup and other impurities without leaving the skin feeling stripped.','Commonly used to leave skin clean and refreshed while helping maintain the skin’s moisture balance. Gentle enough for regular daily use.','{\"sources\": {\"purpose\": [{\"url\": \"https://www.cerave.com/skincare/cleansers/foaming-facial-cleanser\", \"label\": \"CeraVe — Foaming Facial Cleanser for normal to oily skin\"}, {\"url\": \"https://www.neutrogena.com/products/skincare/neutrogena-hydro-boost-hydrating-gel-cleanser-with-hyaluronic-acid-fragrance-free/6806422\", \"label\": \"Neutrogena — Hydro Boost Hydrating Gel Cleanser\"}], \"benefits\": [{\"url\": \"https://www.cerave.com/skincare/cleansers/foaming-facial-cleanser\", \"label\": \"CeraVe — Foaming Facial Cleanser for normal to oily skin\"}], \"description\": [{\"url\": \"https://www.cerave.com/skincare/cleansers/foaming-facial-cleanser\", \"label\": \"CeraVe — Foaming Facial Cleanser for normal to oily skin\"}, {\"url\": \"https://www.neutrogena.com/products/skincare/neutrogena-hydro-boost-hydrating-gel-cleanser-with-hyaluronic-acid-fragrance-free/6806422\", \"label\": \"Neutrogena — Hydro Boost Hydrating Gel Cleanser\"}]}, \"confidence\": \"type-level\", \"researchedAt\": \"2026-10-04\"}'),(5,3,'Hydrating Serum','PRD-00005','A lightweight hydrating serum, typically built around humectants such as hyaluronic acid that draw and hold water in the skin.','bottle',800.00,1800.00,35.000,8.000,NULL,1,0,NULL,NULL,'active','2026-09-19 07:34:33.528','2026-10-03 16:22:51.400',NULL,'Used to replenish moisture and support the skin’s moisture barrier. It is applied after cleansing and before a moisturiser.','Commonly used to boost skin hydration, give skin a smoother and plumper look, and soften the appearance of fine lines caused by dryness.','{\"sources\": {\"purpose\": [{\"url\": \"https://www.health.harvard.edu/medications-and-treatments/hyaluronic-acid-for-skin-benefits-how-to-use-it-and-side-effects\", \"label\": \"Harvard Health — Hyaluronic acid for skin: Benefits and how to use it\"}], \"benefits\": [{\"url\": \"https://pmc.ncbi.nlm.nih.gov/articles/PMC8322246/\", \"label\": \"Efficacy Evaluation of a Topical Hyaluronic Acid Serum in Facial Photoaging (PMC8322246)\"}, {\"url\": \"https://www.health.harvard.edu/medications-and-treatments/hyaluronic-acid-for-skin-benefits-how-to-use-it-and-side-effects\", \"label\": \"Harvard Health — Hyaluronic acid for skin: Benefits and how to use it\"}], \"description\": [{\"url\": \"https://www.health.harvard.edu/medications-and-treatments/hyaluronic-acid-for-skin-benefits-how-to-use-it-and-side-effects\", \"label\": \"Harvard Health — Hyaluronic acid for skin: Benefits and how to use it\"}, {\"url\": \"https://pmc.ncbi.nlm.nih.gov/articles/PMC8322246/\", \"label\": \"Efficacy Evaluation of a Topical Hyaluronic Acid Serum in Facial Photoaging (PMC8322246)\"}]}, \"confidence\": \"type-level\", \"researchedAt\": \"2026-10-04\"}'),(6,3,'Acne Treatment Cream','PRD-00006','An over-the-counter topical cream formulated to help treat mild to moderate acne and blemishes. It is applied directly to the affected areas as part of a daily skincare routine.','bottle',450.00,1200.00,42.000,10.000,NULL,1,0,NULL,NULL,'active','2026-09-19 07:34:33.548','2026-10-03 16:22:51.400',NULL,'Used to help clear up acne pimples and blemishes and to help prevent new ones from forming, by reducing acne-causing bacteria and helping to unclog pores.','Commonly used to reduce the number and appearance of pimples and blemishes, calm inflammation, and support clearer-looking skin with consistent use. Results typically take several weeks.','{\"sources\": {\"purpose\": [{\"url\": \"https://medlineplus.gov/druginfo/meds/a601026.html\", \"label\": \"MedlinePlus — Benzoyl Peroxide Topical\"}, {\"url\": \"https://my.clevelandclinic.org/health/drugs/18363-benzoyl-peroxide-cream-gel-or-lotion\", \"label\": \"Cleveland Clinic — Benzoyl Peroxide: Acne Treatment\"}], \"benefits\": [{\"url\": \"https://my.clevelandclinic.org/health/drugs/18363-benzoyl-peroxide-cream-gel-or-lotion\", \"label\": \"Cleveland Clinic — Benzoyl Peroxide: Acne Treatment\"}, {\"url\": \"https://medlineplus.gov/druginfo/meds/a601026.html\", \"label\": \"MedlinePlus — Benzoyl Peroxide Topical\"}], \"description\": [{\"url\": \"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8d5e7e40-5e61-470a-b8ff-0b2dca3cabb0\", \"label\": \"DailyMed — Acne treatment (benzoyl peroxide) drug facts\"}, {\"url\": \"https://medlineplus.gov/druginfo/meds/a601026.html\", \"label\": \"MedlinePlus — Benzoyl Peroxide Topical\"}]}, \"confidence\": \"type-level\", \"researchedAt\": \"2026-10-04\"}'),(7,2,'LED Therapy Mask','PRD-00007',NULL,'piece',3500.00,0.00,5.000,2.000,NULL,0,0,NULL,NULL,'active','2026-09-19 07:34:33.569','2026-09-19 07:34:33.569',NULL,NULL,NULL,NULL),(8,2,'Disposable Gloves (Box)','PRD-00008',NULL,'box',250.00,0.00,20.000,5.000,NULL,0,1,NULL,NULL,'active','2026-09-19 07:34:33.593','2026-09-19 07:34:33.593',NULL,NULL,NULL,NULL),(9,2,'Sterile Cotton Pads','PRD-00009',NULL,'piece',5.00,0.00,2015.000,500.000,NULL,0,1,NULL,NULL,'active','2026-09-19 07:34:33.614','2026-09-20 05:30:59.974',NULL,NULL,NULL,NULL),(10,4,'Sunscreen SPF50+','PRD-00010','A broad-spectrum sunscreen with SPF 50+, formulated to be applied to the skin before sun exposure and reapplied as directed.','bottle',600.00,1500.00,59.000,15.000,NULL,1,0,NULL,NULL,'active','2026-09-19 07:34:33.631','2026-10-03 16:22:51.400',NULL,'Used to help protect the skin from UVA and UVB radiation, which helps prevent sunburn and reduce the risk of early skin ageing and sun-related skin damage.','Commonly used to help prevent sunburn and protect against sun-related skin ageing when applied as directed. Reapply at least every two hours, and after swimming, sweating or towel drying.','{\"sources\": {\"purpose\": [{\"url\": \"https://www.fda.gov/drugs/understanding-over-counter-medicines/sunscreen-how-help-protect-your-skin-sun\", \"label\": \"FDA — Sunscreen: How to Help Protect Your Skin from the Sun\"}], \"benefits\": [{\"url\": \"https://www.fda.gov/drugs/understanding-over-counter-medicines/sunscreen-how-help-protect-your-skin-sun\", \"label\": \"FDA — Sunscreen: How to Help Protect Your Skin from the Sun\"}], \"description\": [{\"url\": \"https://www.fda.gov/drugs/understanding-over-counter-medicines/sunscreen-how-help-protect-your-skin-sun\", \"label\": \"FDA — Sunscreen: How to Help Protect Your Skin from the Sun\"}, {\"url\": \"https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=cda67d41-d063-4936-a6b9-23376304eb42\", \"label\": \"DailyMed — Broad Spectrum SPF 50 sunscreen drug facts\"}]}, \"confidence\": \"type-level\", \"researchedAt\": \"2026-10-04\"}'),(11,4,'Vitamin C Serum','PRD-00011','A topical serum containing vitamin C (usually L-ascorbic acid), a well-studied antioxidant used in brightening and anti-ageing routines.','bottle',700.00,1600.00,38.000,10.000,NULL,1,0,NULL,NULL,'active','2026-09-19 07:34:33.651','2026-10-03 16:22:51.400',NULL,'Used on the skin to provide antioxidant protection against environmental stress and to help brighten and even out the look of the complexion.','Commonly used to help brighten dull skin, even out skin tone and the look of dark spots, and support the skin’s collagen. It can be used alongside sunscreen; start gradually if the skin is sensitive.','{\"sources\": {\"purpose\": [{\"url\": \"https://health.clevelandclinic.org/vitamin-c-serum\", \"label\": \"Cleveland Clinic — Vitamin C Serum: Benefits, How to Apply\"}, {\"url\": \"https://columbiaskinclinic.com/ask-a-dermatologist/why-you-should-be-using-a-vitamin-c-serum\", \"label\": \"Columbia Skin Clinic — Why You Should Be Using a Vitamin C Serum\"}], \"benefits\": [{\"url\": \"https://health.clevelandclinic.org/vitamin-c-serum\", \"label\": \"Cleveland Clinic — Vitamin C Serum: Benefits, How to Apply\"}, {\"url\": \"https://columbiaskinclinic.com/ask-a-dermatologist/why-you-should-be-using-a-vitamin-c-serum\", \"label\": \"Columbia Skin Clinic — Why You Should Be Using a Vitamin C Serum\"}], \"description\": [{\"url\": \"https://health.clevelandclinic.org/vitamin-c-serum\", \"label\": \"Cleveland Clinic — Vitamin C Serum: Benefits, How to Apply\"}]}, \"confidence\": \"type-level\", \"researchedAt\": \"2026-10-04\"}'),(12,4,'Retinol Night Cream','PRD-00012','A night cream containing retinol, a vitamin A derivative widely used in anti-ageing and blemish-prone skincare. It is applied in the evening.','bottle',550.00,1400.00,30.000,8.000,NULL,1,0,NULL,NULL,'active','2026-09-19 07:34:33.670','2026-10-03 16:22:51.400',NULL,'Used overnight to support the skin’s natural cell renewal and to help improve the look of fine lines, uneven texture, dark spots and clogged pores.','Commonly used to smooth the appearance of fine lines and wrinkles, improve skin texture and tone, and help unclog pores over several weeks of use. Skin can become more sun-sensitive, so daytime sunscreen is important.','{\"sources\": {\"purpose\": [{\"url\": \"https://my.clevelandclinic.org/health/treatments/23293-retinol\", \"label\": \"Cleveland Clinic — Retinol: Cream, Serum, What It Is, Benefits, How To Use\"}, {\"url\": \"https://pubmed.ncbi.nlm.nih.gov/35816071\", \"label\": \"Farris — Retinol: The Ideal Retinoid for Cosmetic Solutions (PubMed 35816071)\"}], \"benefits\": [{\"url\": \"https://pubmed.ncbi.nlm.nih.gov/35816071\", \"label\": \"Farris — Retinol: The Ideal Retinoid for Cosmetic Solutions (PubMed 35816071)\"}, {\"url\": \"https://my.clevelandclinic.org/health/treatments/23293-retinol\", \"label\": \"Cleveland Clinic — Retinol: Cream, Serum, What It Is, Benefits, How To Use\"}], \"description\": [{\"url\": \"https://my.clevelandclinic.org/health/treatments/23293-retinol\", \"label\": \"Cleveland Clinic — Retinol: Cream, Serum, What It Is, Benefits, How To Use\"}]}, \"confidence\": \"type-level\", \"researchedAt\": \"2026-10-04\"}'),(13,1,'Microneedling Cartridges','PRD-00013',NULL,'unit',150.00,0.00,100.000,20.000,NULL,0,1,NULL,NULL,'active','2026-09-19 07:34:33.689','2026-09-19 07:34:33.689',NULL,NULL,NULL,NULL),(14,4,'Collagen Face Mask (10-pack)','PRD-00014','A pack of collagen-infused hydrating face masks. Each mask delivers a concentrated essence to the skin and is left on for a short period as a periodic treatment.','box',800.00,2000.00,22.000,5.000,NULL,1,1,NULL,NULL,'active','2026-09-19 07:34:33.707','2026-10-03 16:22:51.400',NULL,'Used as a hydrating and conditioning treatment to leave skin feeling moisturised, smoother and refreshed. Much of the benefit comes from the hydrating ingredients rather than the collagen itself.','Commonly used to boost short-term hydration, temporarily plump the look of fine lines, and add a smoother, more radiant appearance. The effect is temporary and works best alongside a consistent skincare routine.','{\"sources\": {\"purpose\": [{\"url\": \"https://onlinelibrary.wiley.com/doi/10.1111/jocd.16181\", \"label\": \"Janssens-Böcker et al. — Native collagen sheet mask clinical evaluation\"}], \"benefits\": [{\"url\": \"https://onlinelibrary.wiley.com/doi/10.1111/jocd.16181\", \"label\": \"Janssens-Böcker et al. — Native collagen sheet mask clinical evaluation\"}], \"description\": [{\"url\": \"https://onlinelibrary.wiley.com/doi/10.1111/jocd.16181\", \"label\": \"Janssens-Böcker et al. — Native collagen sheet mask clinical evaluation\"}]}, \"confidence\": \"type-level\", \"researchedAt\": \"2026-10-04\"}'),(15,3,'Aloe Vera Gel','PRD-00015','A soothing topical gel made with aloe vera, known for its high water content and calming, moisturising properties on the skin.','bottle',200.00,500.00,35.000,10.000,NULL,1,1,NULL,NULL,'active','2026-09-19 07:34:33.728','2026-10-03 16:22:51.400',NULL,'Used to hydrate and soothe dry, irritated or sun-exposed skin, and to support the skin’s natural recovery after minor irritation.','Commonly used to moisturise the skin, help calm redness and irritation, and support skin comfort and hydration.','{\"sources\": {\"purpose\": [{\"url\": \"https://pmc.ncbi.nlm.nih.gov/articles/PMC2763764/\", \"label\": \"Surjushe et al. — Aloe vera: A Short Review (PMC2763764)\"}, {\"url\": \"https://pubmed.ncbi.nlm.nih.gov/17026654\", \"label\": \"Dal’Belo et al. — Moisturizing effect of Aloe vera extract (PubMed 17026654)\"}], \"benefits\": [{\"url\": \"https://pubmed.ncbi.nlm.nih.gov/17026654\", \"label\": \"Dal’Belo et al. — Moisturizing effect of Aloe vera extract (PubMed 17026654)\"}, {\"url\": \"https://pmc.ncbi.nlm.nih.gov/articles/PMC2763764/\", \"label\": \"Surjushe et al. — Aloe vera: A Short Review (PMC2763764)\"}], \"description\": [{\"url\": \"https://pmc.ncbi.nlm.nih.gov/articles/PMC2763764/\", \"label\": \"Surjushe et al. — Aloe vera: A Short Review (PMC2763764)\"}]}, \"confidence\": \"type-level\", \"researchedAt\": \"2026-10-04\"}'),(16,1,'Numbing Cream','PRD-00016',NULL,'bottle',300.00,0.00,18.000,5.000,NULL,0,1,NULL,NULL,'active','2026-09-19 07:34:33.749','2026-09-19 07:34:33.749',NULL,NULL,NULL,NULL),(17,2,'Antiseptic Solution','PRD-00017',NULL,'bottle',150.00,0.00,30.000,8.000,NULL,0,1,NULL,NULL,'active','2026-09-19 07:34:33.774','2026-09-19 07:34:33.774',NULL,NULL,NULL,NULL),(18,4,'Jade Roller Set','PRD-00018','A set of facial massage rollers made from jade stone, used with gentle upward strokes on the face and neck as part of a skincare routine.','piece',500.00,1200.00,20.000,5.000,NULL,1,0,NULL,NULL,'active','2026-09-19 07:34:33.794','2026-10-03 16:22:51.400',NULL,'Used as a cooling facial massage tool to help de-puff the face and support circulation and lymphatic drainage. It is often used to help apply serums and creams.','Commonly used for a soothing, cooling massage that may temporarily reduce puffiness and leave skin looking refreshed and more radiant. Evidence for long-term effects is limited.','{\"sources\": {\"purpose\": [{\"url\": \"https://pubmed.ncbi.nlm.nih.gov/36170573\", \"label\": \"Hamp et al. — Gua-sha, Jade Roller, and Facial Massage (PubMed 36170573)\"}], \"benefits\": [{\"url\": \"https://pubmed.ncbi.nlm.nih.gov/36170573\", \"label\": \"Hamp et al. — Gua-sha, Jade Roller, and Facial Massage (PubMed 36170573)\"}], \"description\": [{\"url\": \"https://pubmed.ncbi.nlm.nih.gov/36170573\", \"label\": \"Hamp et al. — Gua-sha, Jade Roller, and Facial Massage (PubMed 36170573)\"}]}, \"confidence\": \"type-level\", \"researchedAt\": \"2026-10-04\"}'),(19,4,'Bump Eraiser (Aftercare for Hot Waxing)','PRD-00019','A concentrated aftercare spot solution designed for use on the skin after hair removal such as waxing, to help manage post-wax bumps and ingrown hairs.','bottle',100.00,250.00,47.000,10.000,NULL,1,0,NULL,NULL,'active','2026-09-19 07:34:33.811','2026-10-03 16:22:51.400',NULL,'Used after waxing or other hair removal to help prevent and calm ingrown hairs, redness and small bumps on the treated area.','Commonly used to help reduce the appearance of post-wax bumps and redness, soothe irritated skin, and support smoother-looking skin when used regularly after hair removal.','{\"sources\": {\"purpose\": [{\"url\": \"https://bumperaiser.com.au/ingrown-hair-treatment\", \"label\": \"Bump eRaiser — Ingrown hair treatment range\"}], \"benefits\": [{\"url\": \"https://bumperaiser.com.au/ingrown-hair-treatment\", \"label\": \"Bump eRaiser — Ingrown hair treatment range\"}, {\"url\": \"https://www.skincare.com/body-care/hair-removal/how-to-care-for-skin-after-waxing\", \"label\": \"Skincare.com — How to Care for Skin After Waxing\"}], \"description\": [{\"url\": \"https://bumperaiser.com.au/ingrown-hair-treatment\", \"label\": \"Bump eRaiser — Ingrown hair treatment range\"}]}, \"confidence\": \"type-level\", \"researchedAt\": \"2026-10-04\"}'),(20,4,'Post Healing Cream (Aftercare for Warts/Skin Tag Removal)','PRD-00020','A topical aftercare cream intended for use on small treated areas after procedures such as wart or skin tag removal.','bottle',60.00,150.00,46.000,10.000,NULL,1,0,NULL,NULL,'active','2026-09-19 07:34:33.834','2026-10-03 16:22:51.400',NULL,'Used after a minor removal procedure to keep the treated area comfortable and moisturised while it heals, following the aftercare advice given by our clinic staff.','Commonly used to support comfort and help keep the treated area conditioned while it heals. Keep the area clean and dry, do not pick at scabs, and protect it from sun exposure.','{\"sources\": {\"purpose\": [{\"url\": \"https://www.mountsinai.org/health-library/selfcare-instructions/skin-lesion-removal-aftercare\", \"label\": \"Mount Sinai — Skin lesion removal aftercare\"}, {\"url\": \"https://myhealth.alberta.ca/Health/aftercareinformation/pages/conditions.aspx?hwid=zc1281\", \"label\": \"MyHealth Alberta — Skin Tag Removal: Care Instructions\"}], \"benefits\": [{\"url\": \"https://www.mountsinai.org/health-library/selfcare-instructions/skin-lesion-removal-aftercare\", \"label\": \"Mount Sinai — Skin lesion removal aftercare\"}, {\"url\": \"https://myhealth.alberta.ca/Health/aftercareinformation/pages/conditions.aspx?hwid=zc1281\", \"label\": \"MyHealth Alberta — Skin Tag Removal: Care Instructions\"}], \"description\": [{\"url\": \"https://www.mountsinai.org/health-library/selfcare-instructions/skin-lesion-removal-aftercare\", \"label\": \"Mount Sinai — Skin lesion removal aftercare\"}]}, \"confidence\": \"type-level\", \"researchedAt\": \"2026-10-04\"}'),(21,NULL,'QA Inactive Test Product','QA-INACTIVE-$(date +%s)',NULL,'piece',50.00,100.00,10.000,1.000,NULL,1,0,NULL,NULL,'inactive','2026-09-29 14:50:29.349','2026-09-29 14:51:18.433','2026-09-29 14:51:18.432',NULL,NULL,NULL),(22,3,'Test','PRD-00021',NULL,'mg',100.00,50.00,10.000,5.000,NULL,1,0,NULL,NULL,'active','2026-09-29 15:04:59.377','2026-09-29 15:05:03.104','2026-09-29 15:05:03.103',NULL,NULL,NULL),(23,1,'Test','PRD-00022',NULL,'mg',600.00,500.00,9.000,5.000,NULL,1,0,NULL,NULL,'inactive','2026-09-29 15:05:25.927','2026-09-29 15:05:46.399','2026-09-29 15:05:46.398',NULL,NULL,NULL),(24,NULL,'QA SKU Fix Test','PRD-00023',NULL,'piece',50.00,100.00,5.000,1.000,NULL,1,0,NULL,NULL,'active','2026-09-29 15:06:51.948','2026-09-29 15:06:51.948','2026-09-29 23:28:18.000',NULL,NULL,NULL),(25,NULL,'QA SKU Fix Test 2','PRD-00024',NULL,'piece',50.00,100.00,5.000,1.000,NULL,1,0,NULL,NULL,'active','2026-09-29 15:06:52.003','2026-09-29 15:06:52.003','2026-09-29 23:28:18.000',NULL,NULL,NULL);
