DROP TABLE IF EXISTS `staff`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `staff` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `first_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `last_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `position` enum('doctor','nurse','aesthetician','therapist','receptionist','manager','head_admin','nail_technician','facialist','nail_and_skin_care_specialist','clinic_head_nurse') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'aesthetician',
  `job_title` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
