  `status` enum('active','on_leave','inactive','terminated') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `hire_date` datetime(3) DEFAULT NULL,
  `date_of_birth` datetime(3) DEFAULT NULL,
